def main():
    parser = _argparse.ArgumentParser(description='ClassLens combined 4-script runner')
    parser.add_argument('--module', choices=['overview','chapters','questions','students'], help='Run one script only')
    parser.add_argument('--all', action='store_true', help='Run all four scripts sequentially')
    parser.add_argument('--extract-only', action='store_true', help='Only extract exact original scripts, do not run')
    parser.add_argument('--out-dir', default='combined_preserved_sources', help='Folder for extracted scripts')
    args = parser.parse_args()

    out_dir = _Path(args.out_dir).resolve()
    written = _extract_sources(out_dir)
    print(f"Extracted preserved source scripts to: {out_dir}")
    for k, p in written.items():
        print(f"  {k:9s} -> {p.name}")

    if args.extract_only:
        return 0

    order = ['overview', 'chapters', 'questions', 'students']
    if args.module:
        order = [args.module]
    elif not args.all:
        print('No module selected. Use --all or --module <overview|chapters|questions|students>.')
        return 0

    final_code = 0
    for key in order:
        code = _run_one(key, written[key])
        if code != 0 and final_code == 0:
            final_code = code
        # continue running next scripts even if one fails, so full coverage still attempts

    try:
        _build_master_report(out_dir, order, final_code)
    except Exception as exc:
        print(f'[MASTER REPORT] Could not build master report: {exc}')

    return final_code


# ==============================================================================
# ADD-ONLY PATCH: SINGLE MASTER REPORT MODE
# This patch does not remove any preserved source line. It only changes how the
# master runner writes and runs the extracted scripts so individual reports do not
# open rapidly during --all. The child scripts still generate their own artifacts,
# but only the master report opens at the end.
# ==============================================================================

_CL_MASTER_SUPPRESS_PREAMBLE = """
# ==============================================================================
# ADD-ONLY PATCH INSERTED BY MASTER RUNNER
# Suppress individual webbrowser.open() calls when running under the combined
# master report so only one final master dashboard opens after all tests finish.
# Original script content starts immediately after this block; no original line is
# removed or edited.
# ==============================================================================
import os as __cl_master_os
if __cl_master_os.environ.get("CLASSLENS_MASTER_SINGLE_REPORT", "") == "1":
    try:
        import webbrowser as __cl_master_webbrowser
        def __cl_master_suppress_open(url, *args, **kwargs):
            print(f"[MASTER SINGLE REPORT] Suppressed individual report popup: {url}")
            return True
        __cl_master_webbrowser.open = __cl_master_suppress_open
        __cl_master_webbrowser.open_new = __cl_master_suppress_open
        __cl_master_webbrowser.open_new_tab = __cl_master_suppress_open
    except Exception as __cl_master_exc:
        print(f"[MASTER SINGLE REPORT] Browser-popup suppress patch failed: {__cl_master_exc}")
# ==============================================================================
# END ADD-ONLY PATCH INSERTED BY MASTER RUNNER
# ==============================================================================
"""

def _extract_sources(base_dir: _Path) -> dict:
    base_dir.mkdir(parents=True, exist_ok=True)
    written = {}
    for key, payload in _SOURCE_PAYLOADS_B64.items():
        out_path = base_dir / _SOURCE_FILENAMES[key]
        original_bytes = _base64.b64decode(payload.encode('ascii'))
        # Add-only preamble: keeps every original line, only prepends a popup suppressor.
        out_path.write_bytes(_CL_MASTER_SUPPRESS_PREAMBLE.encode('utf-8') + original_bytes)
        written[key] = out_path
    return written

def _run_one(key: str, path: _Path) -> int:
    print()
    print(f"{'='*80}")
    print(f"RUNNING {key.upper()} SCRIPT: {path}")
    print(f"{'='*80}")
    print()
    env = _os.environ.copy()
    env.setdefault('PYTHONIOENCODING', 'utf-8')
    env['CLASSLENS_MASTER_SINGLE_REPORT'] = '1'
    started_at = __import__('time').time()
    proc = _subprocess.run([_sys.executable, str(path)], cwd=str(path.parent), env=env, input='\n\n\n', text=True)
    code = int(proc.returncode or 0)
    try:
        _snapshot_module_artifacts(key, path.parent, started_at, code)
    except Exception as exc:
        print(f'[MASTER REPORT] Snapshot failed for {key}: {exc}')
    print()
    print(f"{'='*80}")
    print(f"FINISHED {key.upper()} SCRIPT WITH EXIT CODE {proc.returncode}")
    print(f"{'='*80}")
    print()
    return code



# ============================================================================== 
# ADD-ONLY FINAL PATCH: DEFAULT RUNS ALL MODULES + FORCE OPEN ONLY MASTER REPORT
# This block does not delete or edit any preserved source script line. It only
# overrides the added master runner behavior so: 
#   1) running the file with no args runs all four modules,
#   2) individual child report browser popups stay suppressed,
#   3) one final master report is generated and force-opened at the end,
#   4) the master report always includes Overview, Chapters, Questions, Students
