# ============================================================================== 

try:
    _CL_PREV_BUILD_MASTER_REPORT = _build_master_report
except NameError:
    _CL_PREV_BUILD_MASTER_REPORT = None

try:
    _CL_PREV_RUN_ONE = _run_one
except NameError:
    _CL_PREV_RUN_ONE = None


def _cl_force_open_file(path):
    """Open the final master report reliably on Windows, macOS, Linux."""
    try:
        p = _Path(path).resolve()
        print(f"[MASTER REPORT] Opening final master report: {p}")
        if _sys.platform.startswith('win'):
            try:
                _os.startfile(str(p))
                return True
            except Exception as exc:
                print(f"[MASTER REPORT] os.startfile failed: {exc}")
        try:
            import webbrowser as _cl_webbrowser
            opened = _cl_webbrowser.open(p.as_uri(), new=2)
            if opened:
                return True
        except Exception as exc:
            print(f"[MASTER REPORT] webbrowser.open failed: {exc}")
        try:
            if _sys.platform == 'darwin':
                _subprocess.Popen(['open', str(p)])
                return True
            _subprocess.Popen(['xdg-open', str(p)])
            return True
        except Exception as exc:
            print(f"[MASTER REPORT] OS opener failed: {exc}")
        print(f"[MASTER REPORT] Please open manually: {p}")
        return False
    except Exception as exc:
        print(f"[MASTER REPORT] Force-open failed: {exc}")
        return False


def _run_one(key: str, path: _Path) -> int:
    """Run one extracted module while suppressing only its browser popup."""
    print()
    print(f"{'='*80}")
    print(f"RUNNING {key.upper()} SCRIPT: {path}")
    print(f"{'='*80}")
    print()
    env = _os.environ.copy()
    env.setdefault('PYTHONIOENCODING', 'utf-8')
    env['CLASSLENS_MASTER_SINGLE_REPORT'] = '1'
    env['CLASSLENS_MASTER_MODULE'] = key
    started_at = __import__('time').time()
    proc = _subprocess.run([_sys.executable, str(path)], cwd=str(path.parent), env=env, input='\n\n\n', text=True)
    code = int(proc.returncode or 0)
    try:
        _snapshot_module_artifacts(key, path.parent, started_at, code)
    except Exception as exc:
        print(f'[MASTER REPORT] Snapshot failed for {key}: {exc}')
    print()
    print(f"{'='*80}")
    print(f"FINISHED {key.upper()} SCRIPT WITH EXIT CODE {proc.returncode}")
    print(f"{'='*80}")
    print()
    return code


def _build_master_report(out_dir: _Path, modules, final_code: int):
    """Build old master report, then force-open it once."""
    path = None
    if _CL_PREV_BUILD_MASTER_REPORT:
        path = _CL_PREV_BUILD_MASTER_REPORT(out_dir, modules, final_code)
    else:
        path = _Path(out_dir) / 'classlens_MASTER_ALL_TABS_REPORT.html'
        path.write_text('<html><body><h1>ClassLens Master Report</h1><p>Master builder fallback.</p></body></html>', encoding='utf-8')
    _cl_force_open_file(path)
    return path


def main():
    parser = _argparse.ArgumentParser(description='ClassLens combined 4-script runner')
    parser.add_argument('--module', choices=['overview','chapters','questions','students'], help='Run one script only')
    parser.add_argument('--all', action='store_true', help='Run all four scripts sequentially')
    parser.add_argument('--extract-only', action='store_true', help='Only extract exact original scripts, do not run')
    parser.add_argument('--out-dir', default='combined_preserved_sources', help='Folder for extracted scripts')
    args = parser.parse_args()

    out_dir = _Path(args.out_dir).resolve()
    written = _extract_sources(out_dir)
    print(f"Extracted preserved source scripts to: {out_dir}")
    for k, p in written.items():
        print(f"  {k:9s} -> {p.name}")

    if args.extract_only:
        return 0

    # FINAL PATCH: no-argument run now means run ALL tabs.
    order = ['overview', 'chapters', 'questions', 'students']
    if args.module:
        order = [args.module]
    elif args.all:
        order = ['overview', 'chapters', 'questions', 'students']
    else:
        print('[MASTER RUNNER] No module selected, so running ALL tabs by default: overview, chapters, questions, students.')

    # Reset result list for a clean master report each run.
    try:
        _MASTER_RUN_RESULTS.clear()
    except Exception:
        pass

    final_code = 0
    for key in order:
        code = _run_one(key, written[key])
        if code != 0 and final_code == 0:
            final_code = code
        # Continue next modules even if one fails.

    try:
        master_path = _build_master_report(out_dir, order, final_code)
        print(f'[MASTER REPORT] Final one-report dashboard: {master_path}')
    except Exception as exc:
        print(f'[MASTER REPORT] Could not build/open master report: {exc}')

    return final_code



