def _classlens_webex_send_message(markdown_message):
    try:
        import requests
    except Exception as exc:
        print("[WEBEX] requests package not available:", exc)
        print("[WEBEX] Install with: pip install requests")
        return False

    try:
        print("[WEBEX PRE-SEND ATTACHMENT] Applying Overview master report fix before attachment upload...")
        __cl_force_full_detailed_overview_in_master_now__()
        print("[WEBEX PRE-SEND ATTACHMENT] Overview master report fix complete.")
    except Exception as exc:
        print("[WEBEX PRE-SEND ATTACHMENT] Overview fix failed:", exc)

    _report_path = _classlens_webex_find_report_file()
    url = "https://webexapis.com/v1/messages"
    headers = {"Authorization": f"Bearer {WEBEX_BOT_TOKEN}"}
    data = {
        "roomId": WEBEX_ROOM_ID.strip(),
        "markdown": markdown_message + "\n\nðŸ“Ž **Attached:** Portable master HTML report. Download it from Webex and open in any browser/system."
    }

    try:
        if _report_path and _os.path.exists(_report_path):
            with open(_report_path, "rb") as _fh:
                files = {"files": (_os.path.basename(_report_path), _fh, "text/html")}
                response = requests.post(url, headers=headers, data=data, files=files, timeout=90)
        else:
            response = requests.post(url, headers={**headers, "Content-Type": "application/json"}, json={"roomId": WEBEX_ROOM_ID.strip(), "markdown": data["markdown"]}, timeout=30)
        print("[WEBEX] status:", response.status_code)
        print("[WEBEX] response:", response.text[:500])
        return 200 <= response.status_code < 300
    except Exception as exc:
        print("[WEBEX] send failed:", exc)
        return False



# ==============================================================================
# ADD-ONLY PATCH: STRICT WEBEX PASS/FAIL STATUS
# ==============================================================================
# No original line is removed. This overrides only the Webex failure detector.
# Status becomes PASS only when the master summary shows 0 failed modules.
# Status becomes FAIL only when failed module count is greater than 0.
# Words like "Failed / Warning Highlights" will no longer make the message fail.

def _classlens_webex_extract_failures(report_path):
    import os
    import re

    if not report_path or not os.path.exists(report_path):
        return {
            "status": "UNKNOWN",
            "failed_count": 0,
            "lines": ["Master report file was not found."],
        }

    try:
        with open(report_path, "r", encoding="utf-8", errors="ignore") as f:
            html_text = f.read()
    except Exception as exc:
        return {
            "status": "UNKNOWN",
            "failed_count": 0,
            "lines": [f"Could not read report: {exc}"],
        }

    text_only = re.sub(r"<script[\s\S]*?</script>", " ", html_text, flags=re.I)
    text_only = re.sub(r"<style[\s\S]*?</style>", " ", text_only, flags=re.I)
    text_only = re.sub(r"<[^>]+>", "\n", text_only)
    text_only = text_only.replace("&nbsp;", " ").replace("&#160;", " ")
    text_only = text_only.replace("&amp;", "&").replace("&lt;", "<").replace("&gt;", ">")
    text_only = re.sub(r"\s+", " ", text_only).strip()

    summary_match = re.search(
        r"(\d+)\s+passed\s*[Â·\-\|]\s*(\d+)\s+failed\s*[Â·\-\|]\s*(\d+)\s+modules",
        text_only,
        flags=re.I,
    )

    if summary_match:
        passed_modules = int(summary_match.group(1))
        failed_modules = int(summary_match.group(2))
        total_modules = int(summary_match.group(3))

        if failed_modules == 0:
            return {
                "status": "PASS",
                "failed_count": 0,
                "lines": [f"All modules passed: {passed_modules}/{total_modules}."],
            }

        fail_lines = [f"Module summary: {passed_modules} passed, {failed_modules} failed, {total_modules} modules."]
        module_patterns = [
            r"(Overview Tab Testing|Chapters Tab Testing|Questions Tab Testing|Students Tab Testing)\s+FAIL",
            r"(Overview Tab Testing|Chapters Tab Testing|Questions Tab Testing|Students Tab Testing).*?Exit code\s+([1-9]\d*)",
        ]
        for pat in module_patterns:
            for m in re.finditer(pat, text_only, flags=re.I):
                line = m.group(0).strip()
                if line not in fail_lines:
                    fail_lines.append(line)

        return {
            "status": "FAIL",
            "failed_count": failed_modules,
            "lines": fail_lines[:15],
        }

    if re.search(r"\b100%\b.*?Module Pass Rate", text_only, flags=re.I) or re.search(r"Module Pass Rate.*?\b100%\b", text_only, flags=re.I):
        return {
            "status": "PASS",
            "failed_count": 0,
            "lines": ["Master module pass rate is 100%."],
        }

    strong_fail_lines = []
    raw_lines = [re.sub(r"\s+", " ", x).strip() for x in text_only.split("  ") if x.strip()]
    for line in raw_lines:
        low = line.lower()
        if (
            "final exit code 1" in low
            or "module summary:" in low
            or "exit code 1" in low
            or "status: failed" in low
            or "needs review" in low
            or "mismatch" in low
        ):
            if len(line) <= 260 and line not in strong_fail_lines:
                strong_fail_lines.append(line)
        if len(strong_fail_lines) >= 15:
            break

    if strong_fail_lines:
        return {
            "status": "FAIL",
            "failed_count": len(strong_fail_lines),
            "lines": strong_fail_lines,
        }

    return {
        "status": "PASS",
        "failed_count": 0,
        "lines": ["No failed modules detected."],
    }



