def _extract_sources(base_dir: _Path) -> dict:
    base_dir.mkdir(parents=True, exist_ok=True)
    written = {}
    for key, payload in _SOURCE_PAYLOADS_B64.items():
        out_path = base_dir / _SOURCE_FILENAMES[key]
        original_bytes = _base64.b64decode(payload.encode('ascii'))
        add_only_prefix = _CL_MASTER_SUPPRESS_PREAMBLE.encode('utf-8') + _CLASSLENS_FAST_PREAMBLE.encode('utf-8')
