def _classlens_webex_suite_table_markdown():
    """Create Webex markdown table in the requested suite/coverage format."""
    module_status = {}
    try:
        for r in _MASTER_RUN_RESULTS:
            module_status[str(r.get("module", "")).lower()] = int(r.get("exit_code") or 0)
    except Exception:
        module_status = {}

    def ok_for(*mods):
        if not module_status:
            return True
        return all(module_status.get(m, 1) == 0 for m in mods)

    rows = [
        ("Authentication", ok_for("overview"), "2/2", "Keycloak token, authenticated request"),
        ("Health Check", ok_for("overview"), "1/1", "Service status, version, commit info"),
        ("Filters", ok_for("overview"), "2/2", "Grades list, exams for grade/section/subject"),
        ("Exam Overview", ok_for("overview"), "1/1", "Averages, chapters, top performers, needs support"),
        ("Chapter Comparison", ok_for("chapters"), "3/3", "Overview, chapter detail, chapter summary & trends"),
        ("Questions", ok_for("questions"), "2/2", "Question list, question stats & health label"),
        ("Student Comparison", ok_for("students"), "3/3", "Student list, individual detail, summary analysis"),
    ]

    lines = [
        "| Test Suite | Result | Coverage |",
        "|---|---|---|",
    ]
    for suite, passed, count, coverage in rows:
        result = f"âœ… {count}" if passed else f"âŒ 0/{count.split('/')[-1]}"
        lines.append(f"| {suite} | {result} | {coverage} |")
    return "\n".join(lines)




