def _cl_final_bool_env(name, default='0'):
    try:
        return str(_os.environ.get(name, default)).strip().lower() in ('1','true','yes','y','on')
    except Exception:
        return False


def _cl_final_latest_file(folder, patterns):
    try:
        candidates = []
        for pat in patterns:
            candidates.extend(list(_Path(folder).glob(pat)))
        candidates = [p for p in candidates if p.is_file()]
        if not candidates:
            return None
        candidates.sort(key=lambda p: p.stat().st_mtime, reverse=True)
        return candidates[0]
    except Exception:
        return None


def _cl_final_run_one(key: str, path: _Path) -> int:
    """Run one preserved child script. No timeout is applied unless user passes --module-timeout."""
    import time as _cl_time
    print()
    print(f"{'='*80}")
    print(f"RUNNING {key.upper()} SCRIPT: {path}")
    print(f"{'='*80}")
    print()

    env = _os.environ.copy()
    env.setdefault('PYTHONIOENCODING', 'utf-8')
    env['CLASSLENS_MASTER_SINGLE_REPORT'] = '1'
    env['CLASSLENS_MASTER_MODULE'] = key
    env.setdefault('CLASSLENS_FAST_MODE', '1')
    env.setdefault('CLASSLENS_FAST_MAX_SLEEP', '0.20')
    if getattr(_CL_FINAL_ARGS, 'headless', False):
        env['CLASSLENS_HEADLESS'] = '1'
    else:
        env.setdefault('CLASSLENS_HEADLESS', '1')

    started_at = _cl_time.time()
    log_path = path.parent / f'{key}__console_output.log'
    timeout_value = getattr(_CL_FINAL_ARGS, 'module_timeout', None)
    if getattr(_CL_FINAL_ARGS, 'no_timeout', False):
        timeout_value = None
    if timeout_value is not None:
        try:
            timeout_value = int(timeout_value)
            if timeout_value <= 0:
                timeout_value = None
        except Exception:
            timeout_value = None

    code = 1
    try:
        with open(log_path, 'w', encoding='utf-8', errors='ignore') as lf:
            proc = _subprocess.Popen(
                [_sys.executable, '-u', str(path)],
                cwd=str(path.parent),
                env=env,
                stdin=_subprocess.PIPE,
                stdout=lf,
                stderr=_subprocess.STDOUT,
                text=True,
            )
            try:
                proc.communicate(input='\n\n\n', timeout=timeout_value)
                code = int(proc.returncode or 0)
            except _subprocess.TimeoutExpired:
                code = 124
                try:
                    lf.write(f"\n[MASTER RUNNER] {key} exceeded explicit module timeout {timeout_value} seconds.\n")
                    lf.flush()
                except Exception:
                    pass
                try:
                    proc.kill()
                    proc.communicate(timeout=20)
                except Exception:
                    pass
    except Exception as exc:
        code = 1
        try:
            log_path.write_text(f'[MASTER RUNNER] Could not run {key}: {exc}', encoding='utf-8')
        except Exception:
            pass
        print(f'[MASTER RUNNER] Could not run {key}: {exc}')

    if code == 124:
        try:
            note = path.parent / f'{key}__TIMEOUT_NOTE.json'
            note.write_text('{"module":"%s","exit_code":124,"reason":"explicit module timeout reached"}' % key, encoding='utf-8')
        except Exception:
            pass

    try:
        _snapshot_module_artifacts(key, path.parent, started_at, code)
        try:
            # Always include console output in the artifact list for evidence.
            if _MASTER_RUN_RESULTS and _MASTER_RUN_RESULTS[-1].get('module') == key:
                _MASTER_RUN_RESULTS[-1].setdefault('artifacts', []).append(log_path)
        except Exception:
            pass
    except Exception as exc:
        print(f'[MASTER REPORT] Snapshot failed for {key}: {exc}')

    print()
    print(f"{'='*80}")
    print(f"FINISHED {key.upper()} SCRIPT WITH EXIT CODE {code}")
    print(f"Console log: {log_path}")
    print(f"{'='*80}")
    print()
    return code


def _run_one(key: str, path: _Path) -> int:
    return _cl_final_run_one(key, path)


def _cl_final_send_webex_report(markdown_text, report_path=None):
    try:
        import requests as _requests
    except Exception as exc:
        print('[WEBEX] requests package not available:', exc)
        return False
    try:
        token = globals().get('WEBEX_BOT_TOKEN', '') or _os.environ.get('WEBEX_BOT_TOKEN', '')
        room_id = globals().get('WEBEX_ROOM_ID', '') or _os.environ.get('WEBEX_ROOM_ID', '')
        if not token or not room_id:
            print('[WEBEX] Missing WEBEX_BOT_TOKEN or WEBEX_ROOM_ID.')
            return False
        url = 'https://webexapis.com/v1/messages'
        headers = {'Authorization': f'Bearer {token}'}
        data = {'roomId': room_id.strip(), 'markdown': markdown_text}
        if report_path and _Path(report_path).exists():
            with open(report_path, 'rb') as fh:
                files = {'files': (_Path(report_path).name, fh, 'text/html')}
                response = _requests.post(url, headers=headers, data=data, files=files, timeout=120)
        else:
            response = _requests.post(url, headers={**headers, 'Content-Type': 'application/json'}, json=data, timeout=45)
        print('[WEBEX] status:', response.status_code)
        print('[WEBEX] response:', response.text[:500])
        return 200 <= int(response.status_code) < 300
    except Exception as exc:
        print('[WEBEX] send failed:', exc)
        return False



def _cl_final_seconds_until_run_at(hhmm):
    import datetime as _cl_dt
    try:
        parts = str(hhmm).strip().split(':')
        hh, mm = int(parts[0]), int(parts[1])
        now = _cl_dt.datetime.now()
        target = now.replace(hour=hh, minute=mm, second=0, microsecond=0)
        if target <= now:
            target = target + _cl_dt.timedelta(days=1)
        return max(0, int((target-now).total_seconds()))
    except Exception:
        return 0


def main():
    global _CL_FINAL_ARGS, _CL_FINAL_MASTER_REPORT_PATH
    parser = _argparse.ArgumentParser(description='ClassLens combined 4-script runner - final add-only override')
    parser.add_argument('--module', choices=['overview','chapters','questions','students'], help='Run one script only')
    parser.add_argument('--all', action='store_true', help='Run all four scripts sequentially')
    parser.add_argument('--extract-only', action='store_true', help='Only extract exact original scripts, do not run')
    parser.add_argument('--out-dir', default='combined_preserved_sources', help='Folder for extracted scripts')
    parser.add_argument('--headless', action='store_true', help='Run Chrome in headless mode')
    parser.add_argument('--module-timeout', type=int, default=None, help='Optional per-module timeout in seconds. Omit for full script completion.')
    parser.add_argument('--no-timeout', action='store_true', help='Disable per-module timeout even if provided elsewhere')
    parser.add_argument('--run-at', default='', help='Wait until HH:MM local time, then run once')
    parser.add_argument('--no-webex', action='store_true', help='Do not send Webex notification')
    args, unknown = parser.parse_known_args()
    _CL_FINAL_ARGS = args
    if unknown:
        print('[MASTER RUNNER] Ignoring unknown arguments for compatibility:', unknown)

    if args.run_at:
        delay = _cl_final_seconds_until_run_at(args.run_at)
        if delay > 0:
            import time as _cl_time
            print(f'[MASTER RUNNER] Waiting {delay} seconds until {args.run_at} local time...')
            _cl_time.sleep(delay)

    out_dir = _Path(args.out_dir).resolve()
    written = _extract_sources(out_dir)
    print(f'Extracted preserved source scripts to: {out_dir}')
    for k, p in written.items():
        print(f'  {k:9s} -> {p.name}')

    if args.extract_only:
        return 0

    if args.module:
        order = [args.module]
    else:
        order = ['overview', 'chapters', 'questions', 'students']

    try:
        _MASTER_RUN_RESULTS.clear()
    except Exception:
        pass

    final_code = 0
    for key in order:
        code = _cl_final_run_one(key, written[key])
        if code != 0 and final_code == 0:
            final_code = code

    try:
        _CL_FINAL_MASTER_REPORT_PATH = _build_master_report(out_dir, order, final_code)
        print(f'[MASTER REPORT] Final one-report dashboard: {_CL_FINAL_MASTER_REPORT_PATH}')
    except Exception as exc:
        print(f'[MASTER REPORT] Could not build/open master report: {exc}')
        _CL_FINAL_MASTER_REPORT_PATH = None

    if not args.no_webex:
        try:
            _cl_final_webex_after_run(final_code, out_dir, order)
        except Exception as exc:
            print('[WEBEX] final send failed:', exc)

    return int(final_code or 0)

