def _cl_questions_result_summary_from_artifacts():
    """Extract a concise professional summary for the Questions module from real run artifacts only."""
    import re as _re
    summary = {
        'module_status': 'NOT RUN',
        'exit_code': None,
        'report': None,
        'sections': None,
        'total_questions': None,
        'passed': None,
        'warnings': None,
        'failed': None,
        'pass_rate': None,
        'evidence': [],
    }
    try:
        for r in _MASTER_RUN_RESULTS:
            if str(r.get('module','')).lower() == 'questions':
                code = int(r.get('exit_code') or 0)
                summary['exit_code'] = code
                summary['module_status'] = 'PASS' if code == 0 else f'FAIL exit {code}'
                for p in r.get('artifacts', []) or []:
                    pp = _Path(p)
                    name = pp.name.lower()
                    if pp.suffix.lower() == '.html' and ('questions' in name or 'section' in name or 'report' in name):
                        if summary['report'] is None or 'all_sections' in name:
                            summary['report'] = pp
                    if len(summary['evidence']) < 5:
                        summary['evidence'].append(pp.name)
                break
        rp = summary.get('report')
        if rp and _Path(rp).exists():
            html = _Path(rp).read_text(encoding='utf-8', errors='ignore')
            m = _re.search(r'(\d+)\s*sections\s*Â·\s*(\d+)\s*questions\s*Â·\s*(\d+)%\s*pass rate', html, _re.I)
            if m:
                summary['sections'] = int(m.group(1))
                summary['total_questions'] = int(m.group(2))
                summary['pass_rate'] = int(m.group(3))
            vals = _re.findall(r'<div class="sc-v"[^>]*>(\d+)</div><div class="sc-l">(Sections|Total Questions|Passed|Warnings|Failed|Pass Rate)</div>', html, _re.I)
            for val, label in vals:
                lab = label.lower()
                if lab == 'sections': summary['sections'] = int(val)
                elif lab == 'total questions': summary['total_questions'] = int(val)
                elif lab == 'passed': summary['passed'] = int(val)
                elif lab == 'warnings': summary['warnings'] = int(val)
                elif lab == 'failed': summary['failed'] = int(val)
            pr = _re.search(r'Overall Pass Rate[^<]*</span>\s*<span class="prog-pct">\s*(\d+)%', html, _re.I)
            if pr: summary['pass_rate'] = int(pr.group(1))
    except Exception as exc:
        summary.setdefault('evidence', []).append(f'summary extraction warning: {exc}')
    return summary



