_CL_SKIP_ZZ_NOTICE = "\n\n# ============================================================================== \n# ADD-ONLY RUNTIME PATCH APPLIED BY MASTER: SECTION ZZ INTENTIONALLY SKIPPED\n# ------------------------------------------------------------------------------\n# User request: always skip Section ZZ and continue testing.\n# ============================================================================== \ntry:\n    if 'ALL_SECTIONS' in globals():\n        ALL_SECTIONS = [s for s in ALL_SECTIONS if str(s).strip().upper() != 'ZZ']\n        print('[MASTER PATCH] Section ZZ skipped by request. Remaining sections:', ALL_SECTIONS)\n    if 'SECTION_WHITELIST' in globals() and isinstance(SECTION_WHITELIST, list):\n        SECTION_WHITELIST = [s for s in SECTION_WHITELIST if str(s).strip().upper() != 'ZZ']\nexcept Exception as _skip_zz_runtime_exc:\n    print('[MASTER PATCH] ZZ skip notice failed:', _skip_zz_runtime_exc)\n# ============================================================================== \n"

def _cl_patch_file_to_skip_zz(_path):
    try:
        _p = _Path(_path)
        _txt = _p.read_text(encoding='utf-8', errors='ignore')
        _orig = _txt
        _txt = _txt.replace('ALL_SECTIONS = ["C","H", "I", "J", "K", "L", "M", "N", "O", "P", "Q", "R", "ZZ"]',
                            'ALL_SECTIONS = ["C","H", "I", "J", "K", "L", "M", "N", "O", "P", "Q", "R"]  # ZZ skipped by master add-only patch')
        _txt = _txt.replace('ALL_SECTIONS = ["C", "H", "I", "J", "K", "L", "M", "N", "O", "P", "Q", "R", "ZZ"]',
                            'ALL_SECTIONS = ["C", "H", "I", "J", "K", "L", "M", "N", "O", "P", "Q", "R"]  # ZZ skipped by master add-only patch')
        _txt = _txt.replace("ALL_SECTIONS = ['C','H', 'I', 'J', 'K', 'L', 'M', 'N', 'O', 'P', 'Q', 'R', 'ZZ']",
                            "ALL_SECTIONS = ['C','H', 'I', 'J', 'K', 'L', 'M', 'N', 'O', 'P', 'Q', 'R']  # ZZ skipped by master add-only patch")
        _txt = _txt.replace("ALL_SECTIONS = ['C', 'H', 'I', 'J', 'K', 'L', 'M', 'N', 'O', 'P', 'Q', 'R', 'ZZ']",
                            "ALL_SECTIONS = ['C', 'H', 'I', 'J', 'K', 'L', 'M', 'N', 'O', 'P', 'Q', 'R']  # ZZ skipped by master add-only patch")
        # Also catch compact/minified variants where spacing differs.
        _txt = _txt.replace('"R", "ZZ"]', '"R"]  # ZZ skipped by master add-only patch')
        _txt = _txt.replace('"R","ZZ"]', '"R"]  # ZZ skipped by master add-only patch')
        if _CL_SKIP_ZZ_NOTICE.strip() not in _txt:
            _txt = _txt + _CL_SKIP_ZZ_NOTICE
        if _txt != _orig:
            _p.write_text(_txt, encoding='utf-8')
            print(f'[ADD-ONLY OVERRIDE] Patched extracted script to skip ZZ: {_p.name}')
    except Exception as _cl_patch_zz_exc:
        print(f'[ADD-ONLY OVERRIDE] Could not patch ZZ skip for {_path}: {_cl_patch_zz_exc}')

def _extract_sources(base_dir: _Path) -> dict:
    written = _CL_PREV_EXTRACT_SOURCES_SKIP_ZZ(base_dir) if _CL_PREV_EXTRACT_SOURCES_SKIP_ZZ else {}
    try:
        for _key, _path in (written or {}).items():
            _cl_patch_file_to_skip_zz(_path)
    except Exception as _cl_extract_skip_zz_exc:
        print('[ADD-ONLY OVERRIDE] ZZ skip extraction wrapper failed:', _cl_extract_skip_zz_exc)
    return written

