# ============================================================================== 
# FINAL ADD-ONLY OVERRIDE: CORRECT QUESTION TAB REPORT SELECTION
# ------------------------------------------------------------------------------
# Problem fixed:
# - Questions Tab panel was showing the Chapters HTML report because stale/recent
#   HTML artifacts from the Chapters module were being copied under the questions
#   artifact namespace.
# - This override keeps all original lines and only changes artifact selection at
#   runtime: Questions Tab uses ONLY the report generated by the Questions script.
# ============================================================================== 
try:
    _CL_EXPECTED_PRIMARY_HTML = {
        'overview': ['classlens_full_report_v13.html', 'classlens_all_sections_master_report_v13.html'],
        'chapters': ['classlens_all_sections_final_report.html'],
        'questions': ['classlens_all_sections_report.html'],
        'students': ['classlens_all_sections_report.html'],
    }

    _CL_EXPECTED_JSON_HINTS = {
        'overview': ['classlens_full_data_v13.json', 'classlens_all_sections_master_data_v13.json'],
        'chapters': ['classlens_all_sections_final_report.json', 'classlens_all_sections_final_data.json'],
        'questions': ['classlens_all_sections_report.json', 'classlens_all_sections_data.json'],
        'students': ['students_all_sections.json'],
    }

    def _cl_expected_for_module(_key, _p):
        _name = _p.name.lower()
        _expected_html = [x.lower() for x in _CL_EXPECTED_PRIMARY_HTML.get(_key, [])]
        _expected_json = [x.lower() for x in _CL_EXPECTED_JSON_HINTS.get(_key, [])]
        if _p.suffix.lower() == '.html':
            return _name in _expected_html
        if _p.suffix.lower() == '.json':
            if _name in _expected_json:
                return True
            return _key in _name
        if _p.suffix.lower() in ('.png', '.jpg', '.jpeg'):
            return _key in _name
        return False

    def _snapshot_module_artifacts(key: str, module_dir: _Path, started_at: float, exit_code: int) -> dict:
        artifact_dir = module_dir / _MASTER_ARTIFACT_DIRNAME
        artifact_dir.mkdir(parents=True, exist_ok=True)

        # Remove only this module's previous copied artifacts so the panel cannot
        # display a stale report from a previous run.
        try:
            for _old in artifact_dir.glob(f'{key}__*'):
                try:
                    _old.unlink()
                except Exception:
                    pass
        except Exception:
            pass

        copied = []
        candidates = []
        for pattern in ['*.html', '*.json', '*.png', '*.jpg', '*.jpeg']:
            candidates.extend(list(module_dir.glob(pattern)))

        for p in candidates:
            try:
                if p.name == _MASTER_REPORT_FILE or p.parent.name == _MASTER_ARTIFACT_DIRNAME:
                    continue
                if not _cl_expected_for_module(key, p):
                    continue
                target = artifact_dir / f'{key}__{p.name}'
                _shutil.copy2(p, target)
                copied.append(target)
            except Exception as exc:
                print(f'[MASTER REPORT] Could not snapshot {p}: {exc}')

        result = {
            'module': key,
            'title': _MODULE_TITLES.get(key, key.title()),
            'exit_code': int(exit_code or 0),
            'artifacts': copied,
        }
        _MASTER_RUN_RESULTS.append(result)
        return result

    def _pick_primary_html(result: dict):
        key = result.get('module')
        htmls = [p for p in result.get('artifacts', []) if str(p).lower().endswith('.html')]
        if not htmls:
            return None
        expected = [x.lower() for x in _CL_EXPECTED_PRIMARY_HTML.get(key, [])]
        for wanted in expected:
            for p in htmls:
                # artifacts are named like questions__classlens_all_sections_report.html
                if p.name.lower().endswith(wanted):
                    return p
        preferred = [p for p in htmls if 'report' in p.name.lower()]
        return preferred[0] if preferred else htmls[0]

    _CL_PREV_RUN_ONE_BEFORE_CLEAN_ARTIFACTS = _run_one

    def _run_one(key: str, path: _Path) -> int:
        # Remove the specific stale output names that can contaminate the next
        # module report. This is additive runtime cleanup only; source scripts are
        # not changed or deleted.
        try:
            artifact_dir = path.parent / _MASTER_ARTIFACT_DIRNAME
            artifact_dir.mkdir(parents=True, exist_ok=True)
            for _old in artifact_dir.glob(f'{key}__*'):
                try:
                    _old.unlink()
                except Exception:
                    pass
        except Exception:
            pass
        return _CL_PREV_RUN_ONE_BEFORE_CLEAN_ARTIFACTS(key, path)

    print('[ADD-ONLY OVERRIDE] Question Tab report isolation active: Questions panel will use the Questions script report only.')
except Exception as _cl_question_report_fix_exc:
    print('[ADD-ONLY OVERRIDE] Question Tab report isolation setup failed:', _cl_question_report_fix_exc)
