# ==============================================================================
# FINAL TRUE OVERVIEW V12 DATA FIX
# ==============================================================================
# Reason for previous 0/0 report:
# stale/old Overview runtime was still being used or stale artifacts were embedded.
# This patch has the correct two-argument _run_one(key, path) signature used by
# this master script and forcibly writes the uploaded Overview v12 script before
# the Overview subprocess starts.
# ==============================================================================

try:
    import base64 as _ov12_base64
    import py_compile as _ov12_py_compile
    from pathlib import Path as _ov12_Path

    _OV12_REAL_PAYLOAD_B64 = ''

    def _ov12_write_real_overview_runtime(_path):
        _p = _ov12_Path(_path)
        _p.parent.mkdir(parents=True, exist_ok=True)
        _p.write_bytes(_ov12_base64.b64decode(_OV12_REAL_PAYLOAD_B64))

        _txt = _p.read_text(encoding="utf-8", errors="replace")

        # Runtime safety only on the extracted copy.
        _txt = _txt.replace("KEEP_BROWSER_OPEN = True", "KEEP_BROWSER_OPEN = False")
        _txt = _txt.replace("KEEP_BROWSER_OPEN=True", "KEEP_BROWSER_OPEN=False")
        _txt = _txt.replace("AUTO_OPEN_REPORT  = True", "AUTO_OPEN_REPORT  = False")
        _txt = _txt.replace("AUTO_OPEN_REPORT = True", "AUTO_OPEN_REPORT = False")
        _txt = _txt.replace("AUTO_OPEN_REPORT=True", "AUTO_OPEN_REPORT=False")

        if 'opts.add_argument("--headless=new")' not in _txt and 'def make_driver():' in _txt:
            _txt = _txt.replace(
                'opts.add_argument("--disable-notifications")',
                'opts.add_argument("--disable-notifications")\n'
                '    if "--headless" in sys.argv or os.environ.get("CLASSLENS_HEADLESS") == "1":\n'
                '        opts.add_argument("--headless=new")\n'
                '        opts.add_argument("--window-size=1920,1080")\n'
                '    opts.add_argument("--disable-gpu")\n'
                '    opts.add_argument("--disable-extensions")\n'
                '    opts.add_argument("--disable-dev-shm-usage")\n'
                '    opts.add_argument("--no-sandbox")\n'
                '    opts.add_argument("--disable-popup-blocking")\n'
                '    opts.add_argument("--remote-allow-origins=*")'
            )

        _txt = _txt.replace(
            'input("\\nðŸ‘‰  Press ENTER to close browserâ€¦")',
            'print("\\n[MASTER MODE] Browser close prompt skipped.")'
        )
        _txt = _txt.replace(
            "input('\\nðŸ‘‰  Press ENTER to close browserâ€¦')",
            'print("\\n[MASTER MODE] Browser close prompt skipped.")'
        )

        _p.write_text(_txt, encoding="utf-8")
        try:
            _ov12_py_compile.compile(str(_p), doraise=True)
            print("[OVERVIEW V12 REAL] syntax PASS:", _p)
        except Exception as _compile_exc:
            print("[OVERVIEW V12 REAL] syntax FAIL:", _compile_exc)
        return _p

    def _ov12_clean_stale_outputs(_dir):
        _d = _ov12_Path(_dir)
        _patterns = [
            "overview__*",
            "overview_*",
            "classlens_full_report_v12.html",
            "classlens_full_data_v12.json",
            "classlens_FINAL_COMBINED_ALL_SECTIONS_REPORT_ONLY.html",
            "classlens_FINAL_COMBINED_ALL_SECTIONS_DATA_ONLY.json",
            "classlens_full_report_v13*.html",
            "classlens_full_data_v13*.json",
        ]
        for _pat in _patterns:
            for _old in _d.glob(_pat):
                try:
                    _old.unlink()
                    print("[OVERVIEW V12 REAL] removed stale:", _old.name)
                except Exception:
                    pass

    try:
        _SOURCE_PAYLOADS_B64["overview"] = _OV12_REAL_PAYLOAD_B64
    except Exception as _payload_exc:
        print("[OVERVIEW V12 REAL] payload table update skipped:", _payload_exc)

    try:
        _CL_USER_OVERVIEW_TAB_SCRIPT_B64 = _OV12_REAL_PAYLOAD_B64
    except Exception:
        pass

    _OV12_PREV_EXTRACT_SOURCES = _extract_sources
    def _extract_sources(base_dir):
        _written = _OV12_PREV_EXTRACT_SOURCES(base_dir)
        try:
            _ov_path = _ov12_Path(base_dir) / "01_overview_tab_testing.py"
            _ov12_clean_stale_outputs(base_dir)
            _ov12_write_real_overview_runtime(_ov_path)
            _written["overview"] = _ov_path
            print("[OVERVIEW V12 REAL] extracted Overview replaced with uploaded v12 script.")
        except Exception as _extract_exc:
            print("[OVERVIEW V12 REAL] extract override failed:", _extract_exc)
        return _written

    _OV12_PREV_RUN_ONE = _run_one
    def _run_one(key: str, path):
        if str(key).lower() == "overview":
            try:
                _ov12_clean_stale_outputs(_ov12_Path(path).parent)
                _ov12_write_real_overview_runtime(path)
                print("[OVERVIEW V12 REAL] Overview runtime forced before subprocess.")
            except Exception as _run_force_exc:
                print("[OVERVIEW V12 REAL] pre-run force failed:", _run_force_exc)
        return _OV12_PREV_RUN_ONE(key, path)

    print("[OVERVIEW V12 REAL] Final true Overview v12 data fix is active.")

except Exception as _ov12_outer_exc:
    print("[OVERVIEW V12 REAL] setup failed:", _ov12_outer_exc)

