# keeps Chapters, Questions, and Students modules unchanged.
# ==============================================================================
try:
    import base64 as _cl_ov17_base64
    from pathlib import Path as _cl_ov17_Path

    _CL_OVERVIEW_V17_USER_SCRIPT_B64 = """"""

    try:
        _SOURCE_PAYLOADS_B64["overview"] = _CL_OVERVIEW_V17_USER_SCRIPT_B64
        print("[OVERVIEW V17 OVERRIDE] Active Overview payload replaced with user-supplied v17 script.")
    except Exception as _cl_ov17_payload_exc:
        print("[OVERVIEW V17 OVERRIDE] Payload table update warning:", _cl_ov17_payload_exc)

    try:
        _CL_USER_OVERVIEW_TAB_SCRIPT_B64 = _CL_OVERVIEW_V17_USER_SCRIPT_B64
    except Exception:
        pass

    def _cl_ov17_patch_runtime_copy(_path):
        try:
            _p = _cl_ov17_Path(_path)
            if not _p.exists():
                return
            _txt = _p.read_text(encoding="utf-8", errors="replace")
            _txt = _txt.replace('SECTION_RUN_LIST   = ["C", "H", "I", "J", "K", "L", "M", "N", "O", "P", "Q", "R", "ZZ"]',
                                'SECTION_RUN_LIST   = ["C", "H", "I", "J", "K", "L", "M", "N", "O", "P", "Q", "R"]  # ZZ skipped by master add-only patch')
            _txt = _txt.replace('SECTION_RUN_LIST = ["C", "H", "I", "J", "K", "L", "M", "N", "O", "P", "Q", "R", "ZZ"]',
                                'SECTION_RUN_LIST = ["C", "H", "I", "J", "K", "L", "M", "N", "O", "P", "Q", "R"]  # ZZ skipped by master add-only patch')
            _txt = _txt.replace(', "ZZ"]', ']')
            _txt = _txt.replace(',"ZZ"]', ']')
            if "CLASSLENS_OVERVIEW_V17_MASTER_RUNTIME_PATCH" not in _txt:
                _txt += """\n\n# CLASSLENS_OVERVIEW_V17_MASTER_RUNTIME_PATCH\ntry:\n    KEEP_BROWSER_OPEN = False\n    AUTO_OPEN_REPORT = False\n    if 'SECTION_RUN_LIST' in globals():\n        SECTION_RUN_LIST = [s for s in SECTION_RUN_LIST if str(s).strip().upper() != 'ZZ']\n        print('[OVERVIEW V17 MASTER PATCH] Section ZZ skipped. Sections:', SECTION_RUN_LIST)\nexcept Exception as _overview_v17_master_patch_exc:\n    print('[OVERVIEW V17 MASTER PATCH] runtime patch warning:', _overview_v17_master_patch_exc)\n"""
            _p.write_text(_txt, encoding="utf-8")
            print("[OVERVIEW V17 OVERRIDE] Runtime Overview copy written and patched:", _p)
        except Exception as _cl_ov17_patch_exc:
            print("[OVERVIEW V17 OVERRIDE] Runtime patch warning:", _cl_ov17_patch_exc)

    try:
        _CL_OV17_PREV_EXTRACT_SOURCES = _extract_sources
        def _extract_sources(base_dir):
            _written = _CL_OV17_PREV_EXTRACT_SOURCES(base_dir)
            try:
                _base = _cl_ov17_Path(base_dir)
                _base.mkdir(parents=True, exist_ok=True)
                _overview_path = _base / "01_overview_tab_testing.py"
                _overview_path.write_bytes(_cl_ov17_base64.b64decode(_CL_OVERVIEW_V17_USER_SCRIPT_B64))
                _cl_ov17_patch_runtime_copy(_overview_path)
                if isinstance(_written, dict):
                    _written["overview"] = _overview_path
                print("[OVERVIEW V17 OVERRIDE] Extracted Overview module replaced with user v17 script.")
            except Exception as _cl_ov17_extract_exc:
                print("[OVERVIEW V17 OVERRIDE] Extract override warning:", _cl_ov17_extract_exc)
            return _written
    except Exception as _cl_ov17_extract_hook_exc:
        print("[OVERVIEW V17 OVERRIDE] Extract hook warning:", _cl_ov17_extract_hook_exc)

    try:
        _CL_OV17_PREV_OVERVIEW_JSON_SUMMARY_HTML = _cl_overview_json_summary_html
        def _cl_overview_json_summary_html(_json_file):
            try:
                import json as _json
                import html as _html
                from pathlib import Path as _Path
                if not _json_file or not _Path(_json_file).exists():
                    return _CL_OV17_PREV_OVERVIEW_JSON_SUMMARY_HTML(_json_file)
                _data = _json.loads(_Path(_json_file).read_text(encoding="utf-8", errors="replace"))
                _runs = []
                if isinstance(_data, dict) and isinstance(_data.get("runs"), list):
                    _runs = _data.get("runs")
                elif isinstance(_data, dict) and isinstance(_data.get("sections"), list):
                    _runs = _data.get("sections")
                if not _runs:
                    return _CL_OV17_PREV_OVERVIEW_JSON_SUMMARY_HTML(_json_file)
                _total = _passed = _failed = _warnings = _students = _chapters = 0
                _rows = []
                for _run in _runs:
                    if not isinstance(_run, dict):
                        continue
                    _cfg = _run.get("config", {}) if isinstance(_run.get("config"), dict) else {}
                    _sec = _cfg.get("Section") or _run.get("section_under_test") or "-"
                    _sm = _run.get("summary", {}) if isinstance(_run.get("summary"), dict) else {}
                    _t = int(_sm.get("total", 0) or 0)
                    _p = int(_sm.get("passed", 0) or 0)
                    _f = int(_sm.get("failed", 0) or 0)
                    _w = int(_sm.get("warnings", 0) or 0)
                    _total += _t; _passed += _p; _failed += _f; _warnings += _w
                    _chc = 0
                    _chs = _run.get("chapters", {}) if isinstance(_run.get("chapters"), dict) else {}
                    for _lab in ("Reteach", "Brushup", "On Track"):
                        _cd = _chs.get(_lab, {}) if isinstance(_chs.get(_lab), dict) else {}
                        _chc += len(_cd.get("modal_chapters", []) or []) + len(_cd.get("cards", []) or [])
                    _chapters += _chc
                    _stc = 0
                    _sts = _run.get("students", {}) if isinstance(_run.get("students"), dict) else {}
                    for _cat in ("Weak", "Lagging", "Performing Well"):
                        _sd = _sts.get(_cat, {}) if isinstance(_sts.get(_cat), dict) else {}
                        _stc += len(_sd.get("all", []) or [])
                    _students += _stc
                    _rate = _sm.get("pass_rate", "0%")
                    _rows.append("<tr><td><b>Section " + _html.escape(str(_sec)) + "</b></td><td>" + str(_t) + "</td><td class='good'>" + str(_p) + "</td><td class='bad'>" + str(_f) + "</td><td class='warnc'>" + str(_w) + "</td><td><b>" + _html.escape(str(_rate)) + "</b></td><td>" + str(_chc) + "</td><td>" + str(_stc) + "</td></tr>")
                _rate_total = round((_passed / max(_total, 1)) * 100, 1)
                return (
                    "<div class='grid'>"
                    "<div class='card'><div class='num'>" + str(len(_runs)) + "</div><div class='lbl'>Overview Sections</div></div>"
                    "<div class='card'><div class='num'>" + str(_total) + "</div><div class='lbl'>Overview Tests</div></div>"
                    "<div class='card'><div class='num good'>" + str(_passed) + "</div><div class='lbl'>Overview Passed</div></div>"
                    "<div class='card'><div class='num bad'>" + str(_failed) + "</div><div class='lbl'>Overview Failed</div></div>"
                    "<div class='card'><div class='num warnc'>" + str(_warnings) + "</div><div class='lbl'>Overview Warnings</div></div>"
                    "</div><div class='grid'>"
                    "<div class='card'><div class='num'>" + str(_chapters) + "</div><div class='lbl'>Chapter Data Items</div></div>"
                    "<div class='card'><div class='num'>" + str(_students) + "</div><div class='lbl'>Students Captured</div></div>"
                    "<div class='card'><div class='num'>" + str(_rate_total) + "%</div><div class='lbl'>Overview Overall Rate</div></div>"
                    "</div>"
                    "<table><thead><tr><th>Section</th><th>Total</th><th>Passed</th><th>Failed</th><th>Warnings</th><th>Pass Rate</th><th>Chapter Data</th><th>Students</th></tr></thead><tbody>" + "".join(_rows) + "</tbody></table>"
                )
            except Exception as _ov17_summary_exc:
                print("[OVERVIEW V17 OVERRIDE] v17 master summary warning:", _ov17_summary_exc)
                return _CL_OV17_PREV_OVERVIEW_JSON_SUMMARY_HTML(_json_file)
    except Exception as _cl_ov17_summary_hook_exc:
        print("[OVERVIEW V17 OVERRIDE] Summary hook warning:", _cl_ov17_summary_hook_exc)

    print("[OVERVIEW V17 OVERRIDE] Final Overview v17 replacement is active; other modules remain unchanged.")
except Exception as _cl_ov17_outer_exc:
    print("[OVERVIEW V17 OVERRIDE] Setup failed:", _cl_ov17_outer_exc)
