# ADD-ONLY PATCH: INLINE FULL OVERVIEW SECTION REPORTS IN MASTER REPORT
# ==============================================================================
try:
    import re as _CL_OV_INLINE_RE
    from pathlib import Path as _CL_OV_INLINE_PATH

    def _cl_ov_inline_read_text(_p):
        try:
            _p = _CL_OV_INLINE_PATH(_p)
            if _p.exists() and _p.is_file():
                return _p.read_text(encoding="utf-8", errors="replace")
        except Exception as _exc:
            print("[OVERVIEW INLINE MASTER] read failed:", _p, _exc)
        return ""

    def _cl_ov_inline_section_from_name(_name):
        _s = str(_name)
        _m = _CL_OV_INLINE_RE.search(r'classlens_full_report_v\d+_([A-Za-z0-9]+)\.html$', _s)
        if _m:
            return _m.group(1)
        _m = _CL_OV_INLINE_RE.search(r'_([A-Za-z0-9]+)\.html$', _s)
        if _m:
            return _m.group(1)
        return ""


    def _cl_ov_inline_body(_html):
        _m = _CL_OV_INLINE_RE.search(r"<body[^>]*>(.*?)</body>", _html, flags=_CL_OV_INLINE_RE.I | _CL_OV_INLINE_RE.S)
        return _m.group(1) if _m else _html

    def _cl_ov_inline_styles(_html):
        return "\n".join(_CL_OV_INLINE_RE.findall(r"<style[^>]*>(.*?)</style>", _html, flags=_CL_OV_INLINE_RE.I | _CL_OV_INLINE_RE.S))



    try:
        _CL_OV_INLINE_PREV_BUILD_PORTABLE = _build_portable_master_html
        def _build_portable_master_html(*args, **kwargs):
            _html = _CL_OV_INLINE_PREV_BUILD_PORTABLE(*args, **kwargs)
            _base = kwargs.get("base_dir") or kwargs.get("artifact_dir") or (_CL_OV_INLINE_PATH.cwd() / "combined_preserved_sources")
            _html = _cl_ov_inline_inject(_html, _base)
            print("[OVERVIEW INLINE MASTER] Embedded all full Overview section reports into master report.")
            return _html
    except Exception:
        pass

    try:
        _CL_OV_INLINE_PREV_BUILD_MASTER = globals().get("_build_master_report_html")
        def _build_master_report_html(*args, **kwargs):
            _html = _CL_OV_INLINE_PREV_BUILD_MASTER(*args, **kwargs)
            _base = kwargs.get("base_dir") or kwargs.get("artifact_dir") or (_CL_OV_INLINE_PATH.cwd() / "combined_preserved_sources")
            _html = _cl_ov_inline_inject(_html, _base)
            print("[OVERVIEW INLINE MASTER] Embedded all full Overview section reports into master report.")
            return _html
    except Exception:
        pass

    try:
        _CL_OV_INLINE_ORIG_OPEN = open
        def open(file, mode="r", *args, **kwargs):
            _fh = _CL_OV_INLINE_ORIG_OPEN(file, mode, *args, **kwargs)
            try:
                _fname = str(file).lower()
                _is_master = ("w" in str(mode) or "a" in str(mode) or "+" in str(mode)) and _fname.endswith(".html") and ("master" in _fname or "portable" in _fname)
                if _is_master:
                    class _CL_OV_INLINE_WRITER:
                        def __init__(self, fh, path):
                            self._fh = fh
                            self._path = path
                        def write(self, data):
                            try:
                                if isinstance(data, str) and "full-overview-inline-master" not in data:
                                    data = _cl_ov_inline_inject(data, _CL_OV_INLINE_PATH(self._path).parent)
                                    print("[OVERVIEW INLINE MASTER] Inline Overview data injected while writing:", self._path)
                            except Exception as _exc:
                                print("[OVERVIEW INLINE MASTER] write injection failed:", _exc)
                            return self._fh.write(data)
                        def __getattr__(self, name):
                            return getattr(self._fh, name)
                        def __enter__(self):
                            self._fh.__enter__()
                            return self
                        def __exit__(self, *exc):
                            return self._fh.__exit__(*exc)
                    return _CL_OV_INLINE_WRITER(_fh, file)
            except Exception:
                pass
            return _fh
        print("[OVERVIEW INLINE MASTER] Master HTML write hook active.")
    except Exception as _e:
        print("[OVERVIEW INLINE MASTER] open hook failed:", _e)

    print("[OVERVIEW INLINE MASTER] Full inline Overview section report patch active.")

except Exception as _cl_ov_inline_outer_exc:
    print("[OVERVIEW INLINE MASTER] Patch setup failed:", _cl_ov_inline_outer_exc)
